  if (!fs.existsSync(f)) { console.error("MISSING: " + f); process.exit(1); }
  const s = fs.readFileSync(f, "utf8").trim();
  if (!/^-?\d+(\.\d+)?$/.test(s)) { console.error("NOT NUMERIC: " + f + " -> " + JSON.stringify(s)); process.exit(1); }
  return Number(s);
}
